from pathlib import Path
p=Path('assets/shaders/terrain.gdshader');s=p.read_text(encoding='utf-8-sig');s=s.replace('vec2 tile=p*vec2(.65,.83); tile.x+=floor(tile.y)*.47;','vec2 warped=p+vec2(noise(p*1.9),noise(p*1.7+8.0))*.13;\n   vec2 tile=warped*vec2(.48,.67); tile.x+=floor(tile.y)*.47;');s=s.replace('color*=.82+brick*.32;','color*=.72+brick*.43;\n   float chips=noise(p*11.0);\n   color*=1.0-smoothstep(.70,.87,chips)*.16;');p.write_text(s,encoding='utf-8')
p=Path('assets/shaders/water.gdshader');s=p.read_text();s=s.replace('float ripple=pow(abs(sin(p.x*4.3+p.y*.5+sin(p.y+TIME*.7))),18.0);','float ripple=pow(max(0.0,wave),5.0);');s=s.replace('METALLIC=.35; ROUGHNESS=.22;','METALLIC=.0; ROUGHNESS=.55; SPECULAR=.25;');s=s.replace('wave*.11','wave*.035').replace('TIME)*.10','TIME)*.035');p.write_text(s,encoding='utf-8')
p=Path('scripts/world.gd');s=p.read_text(encoding='utf-8-sig');a=s.index('\tfor i in range(60):');b=s.index('\tvar environment :=',a);s=s[:a]+s[b:];p.write_text(s,encoding='utf-8')
p=Path('export_presets.cfg');s=p.read_text(encoding='utf-8-sig').replace('Riftward_v0.3.exe','Riftward_v0.3.1.exe').replace('0.3.0.0','0.3.1.0');p.write_text(s,encoding='utf-8')
p=Path('启动游戏.cmd');s=p.read_text().replace('if exist "build\\Riftward_v0.3.exe" (','if exist "build\\Riftward_v0.3.1.exe" (\n    start "" "build\\Riftward_v0.3.1.exe"\n) else if exist "build\\Riftward_v0.3.exe" (');p.write_text(s,encoding='ascii')
